```js
// app.js
require('dotenv').config();               // <-- Load .env (add to dev dependencies)
const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ---- Security Middlewares -------------------------------------------------
app.use(helmet());                         // Secure HTTP headers
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [], // restrict origins
  credentials: true,
}));

// Rate limiting: 100 requests per 15 minutes per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- Routes ---------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app, guard this route with auth & hide PII.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});

// ---- Global Error Handler -------------------------------------------------
app.use((err, _req, res, _next) => {
  console.error(err);                     // consider a structured logger
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// ---- Server Startup -------------------------------------------------------
