const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
// const cors = require('cors'); // Uncomment & configure if your API is consumed by browsers

const app = express();

// ---------- Global middleware ----------
app.use(helmet());                     // security headers
app.use(express.json());               // body parsing (future routes)
app.use(morgan('combined'));           // request logging

// Rate limiting: 100 req / 15 min per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
