// ----------------------------------------------------------
// Secure version of the demo Express app
// ----------------------------------------------------------

// Load environment variables (e.g., PORT) from a `.env` file if present.
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// --------------------  Middleware -------------------------
app.use(helmet());                     // Secure HTTP headers
app.use(cors({ origin: false }));     // Disable CORS for public API (adjust as needed)
app.use(express.json());               // Body parser for future POST/PUT routes

// Basic rate limiting: 100 requests per IP per 15 minutes
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ----------------------------------------------------------
// Routes
// ----------------------------------------------------------

